python - <<'PY'
from solver import paginate_records

records = [{'id': x} for x in 'abcde']
assert paginate_records(records, limit=2) == {'items': records[:2], 'next_after': 'b'}
assert paginate_records(records, after='b', limit=2) == {'items': records[2:4], 'next_after': 'd'}
assert paginate_records(records, after='d', limit=2) == {'items': records[4:], 'next_after': None}
assert paginate_records(records, after='e', limit=2) == {'items': [], 'next_after': None}
for bad in (True, 0, 101, 1.5, '2'):
    try: paginate_records(records, limit=bad)
    except ValueError: pass
    else: raise AssertionError(bad)
for bad_records in ([{'id': ''}], [{'id': 1}], [{'id': 'a'}, {'id': 'a'}], [None]):
    try: paginate_records(bad_records)
    except ValueError: pass
    else: raise AssertionError(bad_records)
for bad_after in ('z', 1, True):
    try: paginate_records(records, after=bad_after)
    except ValueError: pass
    else: raise AssertionError(bad_after)
assert records == [{'id': x} for x in 'abcde']
print('boundary checks passed')
